/**
 * Renderer contract for a scalar field. Providers own their texture and view; frame()
 * advances content without changing either identity.
 */
export function assertFieldProvider(provider) {
  if (!provider?.texture || !provider?.view || !Number.isInteger(provider.size) || provider.size <= 0) {
    throw new TypeError('A field provider requires texture, view, and a positive integer size');
  }
  if (typeof provider.frame !== 'function') throw new TypeError('A field provider requires frame()');
  return provider;
}

export function createSyntheticFieldProvider(device, registry, {
  size = 512,
  label = 'synthetic-look-field',
} = {}) {
  if (!device?.queue) throw new TypeError('A GPUDevice is required');
  if (!registry?.createTexture) throw new TypeError('A GPU registry is required');

  const texture = registry.createTexture({
    label,
    size: [size, size, 1],
    format: 'r32float',
    usage: GPUTextureUsage.COPY_DST | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.STORAGE_BINDING,
  });
  const view = texture.createView({ label: `${label}-view` });
  const floatsPerRow = Math.ceil((size * 4) / 256) * 64;
  const upload = new Float32Array(floatsPerRow * size);
  let lastPaintedPhase = Number.NaN;

  function frame({ timeMs = 0, force = false } = {}) {
    const paintedPhase = Math.floor(timeMs / 250) / 16;
    if (!force && paintedPhase === lastPaintedPhase) return;
    paintSyntheticField(upload, size, floatsPerRow, paintedPhase);
    device.queue.writeTexture(
      { texture },
      upload,
      { bytesPerRow: floatsPerRow * 4, rowsPerImage: size },
      [size, size, 1],
    );
    lastPaintedPhase = paintedPhase;
  }

  const provider = {
    texture,
    view,
    size,
    frame,
    destroy() {
      registry.destroy(texture);
    },
  };
  frame({ force: true });
  return assertFieldProvider(provider);
}

export function syntheticFieldValue(uvX, uvY, phase = 0) {
  const wave = 0.5 + 0.5 * Math.sin((uvX * 5.1 + uvY * 2.7 + phase) * Math.PI * 2);
  const ringDistance = Math.abs(Math.hypot(uvX - 0.34, uvY - 0.48) - 0.22);
  const ring = 1 - smoothstep(0.018, 0.06, ringDistance);
  const paintedFront = smoothstep(-0.05, 0.05, uvX - 0.64 + 0.08 * Math.sin(uvY * 14 + phase));
  const noise = hash2d(Math.floor(uvX * 257), Math.floor(uvY * 257));
  return Math.min(1, Math.max(0, 0.06 + wave * 0.19 + ring * 0.58 + paintedFront * 0.42 + noise * 0.08));
}

function paintSyntheticField(target, size, floatsPerRow, phase) {
  for (let texelY = 0; texelY < size; texelY += 1) {
    for (let texelX = 0; texelX < size; texelX += 1) {
      target[texelY * floatsPerRow + texelX] = syntheticFieldValue(
        (texelX + 0.5) / size,
        (texelY + 0.5) / size,
        phase,
      );
    }
  }
}

function smoothstep(low, high, value) {
  const t = Math.min(1, Math.max(0, (value - low) / (high - low)));
  return t * t * (3 - 2 * t);
}

function hash2d(x, y) {
  let value = Math.imul(x ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(y, 0xc2b2ae35);
  value ^= value >>> 16;
  return (value >>> 0) / 0xffffffff;
}

const INCLUDE_LINE = /^[ \t]*\/\/#include[ \t]+"([^"]+)"[ \t]*$/gm;
const CONSTANT_TOKEN = /\$\{([A-Z][A-Z0-9_]*)\}/g;

export async function preprocessWgsl(source, {
  constants = {},
  resolveInclude,
  sourceName = '<inline>',
} = {}) {
  const expanded = await expandIncludes(String(source), sourceName, [], resolveInclude);
  return expanded.replace(CONSTANT_TOKEN, (_, name) => {
    if (!Object.hasOwn(constants, name)) {
      throw new Error(`Missing WGSL constant ${name} in ${sourceName}`);
    }
    return formatConstant(constants[name], name);
  });
}

export async function fetchWgsl(url, {
  constants = {},
  fetchImpl = globalThis.fetch,
} = {}) {
  if (typeof fetchImpl !== 'function') throw new TypeError('fetchWgsl requires fetch');
  const cache = new Map();

  async function load(resourceUrl) {
    const absoluteUrl = String(resourceUrl);
    if (cache.has(absoluteUrl)) return cache.get(absoluteUrl);
    const response = await fetchImpl(absoluteUrl, { cache: 'no-store' });
    if (!response.ok) throw new Error(`WGSL fetch failed (${response.status}) for ${absoluteUrl}`);
    const text = await response.text();
    cache.set(absoluteUrl, text);
    return text;
  }

  const entryUrl = new URL(url, globalThis.location?.href || 'http://local/').href;
  const source = await load(entryUrl);
  return preprocessWgsl(source, {
    constants,
    sourceName: entryUrl,
    resolveInclude: async (includePath, parentName) => {
      const includeUrl = new URL(includePath, parentName).href;
      return { source: await load(includeUrl), sourceName: includeUrl };
    },
  });
}

async function expandIncludes(source, sourceName, stack, resolveInclude) {
  if (stack.includes(sourceName)) {
    throw new Error(`WGSL include cycle: ${[...stack, sourceName].join(' -> ')}`);
  }
  const nextStack = [...stack, sourceName];
  const includeLine = new RegExp(INCLUDE_LINE.source, INCLUDE_LINE.flags);
  let output = '';
  let cursor = 0;
  for (let match = includeLine.exec(source); match; match = includeLine.exec(source)) {
    output += source.slice(cursor, match.index);
    if (!resolveInclude) throw new Error(`Cannot resolve WGSL include "${match[1]}" from ${sourceName}`);
    const resolved = await resolveInclude(match[1], sourceName);
    if (resolved === undefined || resolved === null) {
      throw new Error(`Missing WGSL include "${match[1]}" from ${sourceName}`);
    }
    const includedSource = typeof resolved === 'string' ? resolved : resolved.source;
    const includedName = typeof resolved === 'string' ? match[1] : (resolved.sourceName || match[1]);
    output += await expandIncludes(String(includedSource), includedName, nextStack, resolveInclude);
    cursor = match.index + match[0].length;
  }
  return output + source.slice(cursor);
}

function formatConstant(value, name) {
  if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  if (typeof value === 'boolean') return String(value);
  if (typeof value === 'string') return value;
  throw new TypeError(`WGSL constant ${name} must be a finite number, boolean, or string`);
}

/**
 * Creates the only clock interface consumed by game timelines and schedulers.
 * Changing timeScale preserves continuity, which lets tests accelerate a running flow.
 */
export function createClock({ read = defaultMonotonicNow, initialTimeScale = 1 } = {}) {
  let sourceAnchorMs = read();
  let timelineAnchorMs = sourceAnchorMs;
  let currentTimeScale = requirePositiveScale(initialTimeScale);

  return {
    now() {
      return timelineAnchorMs + (read() - sourceAnchorMs) * currentTimeScale;
    },

    get timeScale() {
      return currentTimeScale;
    },

    set timeScale(nextTimeScale) {
      const sourceNowMs = read();
      timelineAnchorMs += (sourceNowMs - sourceAnchorMs) * currentTimeScale;
      sourceAnchorMs = sourceNowMs;
      currentTimeScale = requirePositiveScale(nextTimeScale);
    },
  };
}

function defaultMonotonicNow() {
  return globalThis.performance?.now?.() ?? Date.now();
}

function requirePositiveScale(value) {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError('timeScale must be a positive finite number');
  }
  return value;
}

export const gameClock = createClock();

const PROBE_FEATURES = Object.freeze([
  'shader-f16',
  'float32-filterable',
  'texture-formats-tier1',
]);

/**
 * Acquires an adapter and device without turning expected capability gaps into thrown errors.
 * Callers render the returned report; only programmer errors passed into hooks may escape.
 */
export async function acquireDevice({
  gpu = globalThis.navigator?.gpu,
  powerPreference = 'high-performance',
  forceFallbackAdapter = false,
  requiredFeatures = [],
  optionalFeatures = PROBE_FEATURES,
  requiredLimits,
  onDeviceLost,
} = {}) {
  const report = {
    ok: false,
    stage: 'availability',
    message: '',
    adapter: null,
    device: null,
    adapterInfo: {},
    adapterFeatures: [],
    enabledFeatures: [],
    missingRequiredFeatures: [],
  };

  if (!gpu) {
    report.message = 'WebGPU is not exposed by this browser.';
    return report;
  }

  try {
    report.stage = 'adapter';
    report.adapter = await gpu.requestAdapter({ powerPreference, forceFallbackAdapter });
    if (!report.adapter) {
      report.message = 'No WebGPU adapter matched the request.';
      return report;
    }

    report.adapterInfo = await readAdapterInfo(report.adapter);
    report.adapterFeatures = [...report.adapter.features].sort();
    report.missingRequiredFeatures = requiredFeatures.filter((feature) => !report.adapter.features.has(feature));
    if (report.missingRequiredFeatures.length > 0) {
      report.message = `Required WebGPU features are unavailable: ${report.missingRequiredFeatures.join(', ')}`;
      report.stage = 'feature-negotiation';
      return report;
    }

    report.enabledFeatures = [...new Set([...requiredFeatures, ...optionalFeatures])]
      .filter((feature) => report.adapter.features.has(feature));
    report.stage = 'device';
    report.device = await report.adapter.requestDevice({
      requiredFeatures: report.enabledFeatures,
      ...(requiredLimits ? { requiredLimits } : {}),
    });
    report.device.lost.then((lostInfo) => {
      onDeviceLost?.({ reason: lostInfo.reason, message: lostInfo.message });
    });
    report.ok = true;
    report.stage = 'ready';
    report.message = 'WebGPU device acquired.';
    return report;
  } catch (error) {
    report.message = error instanceof Error ? error.message : String(error);
    report.errorName = error?.name || 'Error';
    return report;
  }
}

export async function readAdapterInfo(adapter) {
  let info = adapter.info;
  if (!info && typeof adapter.requestAdapterInfo === 'function') info = await adapter.requestAdapterInfo();
  if (!info) return {};
  const names = new Set([
    ...Object.keys(info),
    'vendor', 'architecture', 'device', 'description', 'isFallbackAdapter', 'subgroupMinSize', 'subgroupMaxSize',
  ]);
  return Object.fromEntries([...names]
    .filter((name) => info[name] !== undefined)
    .map((name) => [name, info[name]]));
}

/**
 * A development-only validation scope. It always balances push/pop, even when operation throws.
 */
export async function withGpuErrorScope(device, label, operation, {
  enabled = true,
  filter = 'validation',
  onError,
} = {}) {
  if (!enabled) return { value: await operation(), error: null };
  device.pushErrorScope(filter);
  let value;
  let thrown;
  try {
    value = await operation();
  } catch (error) {
    thrown = error;
  }
  const error = await device.popErrorScope();
  if (error) onError?.({ label, filter, message: error.message });
  if (thrown) throw thrown;
  return { value, error };
}

