const BYTES_PER_TEXEL = Object.freeze({
  r8unorm: 1,
  r16float: 2,
  r32float: 4,
  r32uint: 4,
  rg16float: 4,
  rg32float: 8,
  rgba8unorm: 4,
  'rgba8unorm-srgb': 4,
  rgba16float: 8,
  rgba32float: 16,
  depth24plus: 4,
  depth32float: 4,
});

export class GpuRegistry {
  #device;
  #records = new Map();

  constructor(device) {
    if (!device?.createBuffer || !device?.createTexture) throw new TypeError('GpuRegistry requires a GPUDevice');
    this.#device = device;
  }

  createBuffer(descriptor) {
    requireLabel(descriptor?.label, 'buffer');
    const resource = this.#device.createBuffer(descriptor);
    this.#records.set(resource, Object.freeze({
      kind: 'buffer',
      label: descriptor.label,
      bytes: descriptor.size,
      details: { size: descriptor.size, usage: descriptor.usage },
    }));
    return resource;
  }

  createTexture(descriptor) {
    requireLabel(descriptor?.label, 'texture');
    const resource = this.#device.createTexture(descriptor);
    const extent = normalizeExtent(descriptor.size);
    this.#records.set(resource, Object.freeze({
      kind: 'texture',
      label: descriptor.label,
      bytes: calculateTextureBytes(descriptor),
      details: {
        size: extent,
        format: descriptor.format,
        mipLevelCount: descriptor.mipLevelCount || 1,
        sampleCount: descriptor.sampleCount || 1,
      },
    }));
    return resource;
  }

  destroy(resource) {
    const known = this.#records.delete(resource);
    if (known) resource.destroy();
    return known;
  }

  totalBytes() {
    let total = 0;
    for (const record of this.#records.values()) total += record.bytes;
    return total;
  }

  dump() {
    return [...this.#records.values()]
      .map((record) => ({ ...record, details: { ...record.details } }))
      .sort((a, b) => b.bytes - a.bytes || a.label.localeCompare(b.label));
  }
}

export function calculateTextureBytes(descriptor) {
  const bytesPerTexel = BYTES_PER_TEXEL[descriptor.format];
  if (!bytesPerTexel) throw new Error(`Byte accounting is undefined for texture format ${descriptor.format}`);
  const { width, height, depthOrArrayLayers } = normalizeExtent(descriptor.size);
  const mipLevelCount = descriptor.mipLevelCount || 1;
  const sampleCount = descriptor.sampleCount || 1;
  const shrinksInDepth = descriptor.dimension === '3d';
  let texelCount = 0;
  for (let level = 0; level < mipLevelCount; level += 1) {
    texelCount += Math.max(1, width >> level)
      * Math.max(1, height >> level)
      * (shrinksInDepth ? Math.max(1, depthOrArrayLayers >> level) : depthOrArrayLayers);
  }
  return texelCount * bytesPerTexel * sampleCount;
}

function normalizeExtent(size) {
  if (typeof size === 'number') return { width: size, height: 1, depthOrArrayLayers: 1 };
  if (Array.isArray(size)) {
    return { width: size[0], height: size[1] || 1, depthOrArrayLayers: size[2] || 1 };
  }
  return {
    width: size.width,
    height: size.height || 1,
    depthOrArrayLayers: size.depthOrArrayLayers || 1,
  };
}

function requireLabel(label, kind) {
  if (typeof label !== 'string' || label.trim() === '') throw new Error(`Every GPU ${kind} requires a label`);
}
/**
 * Renderer contract for a scalar field. Providers own their texture and view; frame()
 * advances content without changing either identity.
 */
export function assertFieldProvider(provider) {
  if (!provider?.texture || !provider?.view || !Number.isInteger(provider.size) || provider.size <= 0) {
    throw new TypeError('A field provider requires texture, view, and a positive integer size');
  }
  if (typeof provider.frame !== 'function') throw new TypeError('A field provider requires frame()');
  return provider;
}

export function createSyntheticFieldProvider(device, registry, {
  size = 512,
  label = 'synthetic-look-field',
} = {}) {
  if (!device?.queue) throw new TypeError('A GPUDevice is required');
  if (!registry?.createTexture) throw new TypeError('A GPU registry is required');

  const texture = registry.createTexture({
    label,
    size: [size, size, 1],
    format: 'r32float',
    usage: GPUTextureUsage.COPY_DST | GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.STORAGE_BINDING,
  });
  const view = texture.createView({ label: `${label}-view` });
  const floatsPerRow = Math.ceil((size * 4) / 256) * 64;
  const upload = new Float32Array(floatsPerRow * size);
  let lastPaintedPhase = Number.NaN;

  function frame({ timeMs = 0, force = false } = {}) {
    const paintedPhase = Math.floor(timeMs / 250) / 16;
    if (!force && paintedPhase === lastPaintedPhase) return;
    paintSyntheticField(upload, size, floatsPerRow, paintedPhase);
    device.queue.writeTexture(
      { texture },
      upload,
      { bytesPerRow: floatsPerRow * 4, rowsPerImage: size },
      [size, size, 1],
    );
    lastPaintedPhase = paintedPhase;
  }

  const provider = {
    texture,
    view,
    size,
    frame,
    destroy() {
      registry.destroy(texture);
    },
  };
  frame({ force: true });
  return assertFieldProvider(provider);
}

export function syntheticFieldValue(uvX, uvY, phase = 0) {
  const wave = 0.5 + 0.5 * Math.sin((uvX * 5.1 + uvY * 2.7 + phase) * Math.PI * 2);
  const ringDistance = Math.abs(Math.hypot(uvX - 0.34, uvY - 0.48) - 0.22);
  const ring = 1 - smoothstep(0.018, 0.06, ringDistance);
  const paintedFront = smoothstep(-0.05, 0.05, uvX - 0.64 + 0.08 * Math.sin(uvY * 14 + phase));
  const noise = hash2d(Math.floor(uvX * 257), Math.floor(uvY * 257));
  return Math.min(1, Math.max(0, 0.06 + wave * 0.19 + ring * 0.58 + paintedFront * 0.42 + noise * 0.08));
}

function paintSyntheticField(target, size, floatsPerRow, phase) {
  for (let texelY = 0; texelY < size; texelY += 1) {
    for (let texelX = 0; texelX < size; texelX += 1) {
      target[texelY * floatsPerRow + texelX] = syntheticFieldValue(
        (texelX + 0.5) / size,
        (texelY + 0.5) / size,
        phase,
      );
    }
  }
}

function smoothstep(low, high, value) {
  const t = Math.min(1, Math.max(0, (value - low) / (high - low)));
  return t * t * (3 - 2 * t);
}

function hash2d(x, y) {
  let value = Math.imul(x ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(y, 0xc2b2ae35);
  value ^= value >>> 16;
  return (value >>> 0) / 0xffffffff;
}
