      || isNonFinite(agent.heading) || isNonFinite(agent.reserve)) {
    atomicAdd(&stateHash.nonFinite, 1u);
  }
}

@compute @workgroup_size(${FIELD_WORKGROUP_SIZE}, ${FIELD_WORKGROUP_SIZE})
fn hashField(@builtin(global_invocation_id) invocation: vec3<u32>) {
  let size = fieldSize();
  if (invocation.x >= size || invocation.y >= size) { return; }
  let value = textureLoad(field, vec2<i32>(invocation.xy), 0).r;
  let index = invocation.y * size + invocation.x;
  let hash = pcgHash32(bitcast<u32>(value) ^ pcgHash32(index));
  atomicAdd(&stateHash.fieldSum, hash);
  atomicXor(&stateHash.fieldXor, rotateLeft32(hash, 7u));
  if (isNonFinite(value)) { atomicAdd(&stateHash.nonFinite, 1u); }
}

import { AGENT_WORKGROUP_SIZE, FIELD_WORKGROUP_SIZE } from './constants.js';

export function encodeSimulationStep(encoder, pipelines, bindings, resources, {
  agentParity,
  blurIterations,
  oatDirty,
  capacityDispatch = false,
}) {
  const nextParity = agentParity ^ 1;
  const fieldGroups = Math.ceil(resources.fieldSize / FIELD_WORKGROUP_SIZE);
  const capacityGroups = Math.ceil(resources.capacity / AGENT_WORKGROUP_SIZE);
  encoder.pushDebugGroup('flat-torus simulation step');
  encoder.clearBuffer(resources.crowdAtomic);
  encoder.clearBuffer(resources.exposureAtomic);
  encoder.clearBuffer(resources.countBuffers[nextParity]);
  encoder.clearBuffer(resources.allocatorDebug);
  encoder.clearBuffer(resources.childOwnership);

  if (oatDirty) encodeFieldPass(encoder, 'oat-field refresh', pipelines.oat, bindings.oat, fieldGroups);

  encodeAgentPass(encoder, 'crowd scatter', pipelines.crowdScatter, bindings.crowdScatter[agentParity], {
    indirect: resources.dispatchArgs,
  });
  encodeFieldPass(encoder, 'crowd fixed-point resolve', pipelines.crowdResolve, bindings.crowdResolve, fieldGroups);
  var densityIndex = 0;
  for (let iteration = 0; iteration < blurIterations; iteration += 1) {
    encodeFieldPass(encoder, `crowd blur ${iteration + 1}/${blurIterations}`,
      pipelines.crowdBlur, bindings.crowdFilter[densityIndex], fieldGroups);
    densityIndex ^= 1;
  }
  encodeFieldPass(encoder, 'crowd clamp and quantize',
    pipelines.crowdQuantize, bindings.crowdFilter[densityIndex], fieldGroups);
  densityIndex ^= 1;

  encodeAgentPass(encoder, 'advance surviving parents', pipelines.advance,
    bindings.advance[agentParity][densityIndex], capacityDispatch
      ? { direct: capacityGroups }
      : { indirect: resources.dispatchArgs });
  encodeSinglePass(encoder, 'freeze survivor count', pipelines.prepare, bindings.indirect[nextParity]);
  encodeAgentPass(encoder, 'admit children', pipelines.birth, bindings.birth[nextParity], capacityDispatch
    ? { direct: capacityGroups }
    : { indirect: resources.dispatchArgs });
  encodeSinglePass(encoder, 'finalize population', pipelines.finalize, bindings.indirect[nextParity]);

  // Legacy order is agents -> diffuse -> exposure -> delta. New deposits therefore
  // remain sharp until the following step.
  encodeFieldPass(encoder, 'dynamic field diffuse and decay', pipelines.diffuse, bindings.diffuse, fieldGroups);
  encodeAgentPass(encoder, 'food exposure scatter', pipelines.exposure, bindings.exposure[nextParity], {
    indirect: resources.dispatchArgs,
  });
  encodeFieldPass(encoder, 'apply food exposure delta', pipelines.delta, bindings.delta, fieldGroups);
  encoder.popDebugGroup();
  return { nextParity, densityIndex };
}

export function encodeStateHash(encoder, pipelines, bindings, resources, agentParity) {
  const fieldGroups = Math.ceil(resources.fieldSize / FIELD_WORKGROUP_SIZE);
  encoder.clearBuffer(resources.stateHash);
  encodeAgentPass(encoder, 'hash agent state set', pipelines.hashAgents, bindings.hash[agentParity], {
    indirect: resources.dispatchArgs,
  });
  encodeFieldPass(encoder, 'hash dynamic field', pipelines.hashField, bindings.hash[agentParity], fieldGroups);
}

function encodeAgentPass(encoder, label, pipeline, bindGroup, dispatch) {
  const pass = encoder.beginComputePass({ label });
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  if (dispatch.indirect) pass.dispatchWorkgroupsIndirect(dispatch.indirect, 0);
  else pass.dispatchWorkgroups(dispatch.direct);
  pass.end();
}

function encodeFieldPass(encoder, label, pipeline, bindGroup, groups) {
  const pass = encoder.beginComputePass({ label });
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(groups, groups);
  pass.end();
}

function encodeSinglePass(encoder, label, pipeline, bindGroup) {
  const pass = encoder.beginComputePass({ label });
  pass.setPipeline(pipeline);
  pass.setBindGroup(0, bindGroup);
  pass.dispatchWorkgroups(1);
  pass.end();
}
import {
  AGENT_BYTES,
  MAX_OATS,
} from './constants.js';
import { PARAM_BUFFER_BYTES } from './params-layout.js';

const bufferUsage = (copySrc = false, copyDst = true) => GPUBufferUsage.STORAGE
  | (copySrc ? GPUBufferUsage.COPY_SRC : 0)
  | (copyDst ? GPUBufferUsage.COPY_DST : 0);

export function createSimulationResources(registry, { fieldSize, capacity }) {
  const fieldTexels = fieldSize * fieldSize;
  const makeBuffer = (label, size, usage) => registry.createBuffer({ label, size, usage });
  const makeField = (label) => registry.createTexture({
    label,
    size: [fieldSize, fieldSize, 1],
    format: 'r32float',
    usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.STORAGE_BINDING
      | GPUTextureUsage.COPY_SRC | GPUTextureUsage.COPY_DST,
  });

  const agentBuffers = [0, 1].map((index) => makeBuffer(
    `sim-agents-${index}`,
    capacity * AGENT_BYTES,
    bufferUsage(true),
  ));
  const countBuffers = [0, 1].map((index) => makeBuffer(
    `sim-count-${index}`,
    4,
    bufferUsage(true),
  ));
  const dynamicFields = [makeField('sim-field-canonical'), makeField('sim-field-diffuse-scratch')];
  const crowdFields = [makeField('sim-crowd-0'), makeField('sim-crowd-1')];
  const oatField = makeField('sim-oat-field');
  const resources = {
    fieldSize,
    fieldTexels,
    capacity,
    agentBuffers,
    countBuffers,
    dynamicFields,
    dynamicFieldViews: dynamicFields.map((texture, index) => texture.createView({ label: `sim-field-view-${index}` })),
    crowdFields,
    crowdFieldViews: crowdFields.map((texture, index) => texture.createView({ label: `sim-crowd-view-${index}` })),
    oatField,
    oatFieldView: oatField.createView({ label: 'sim-oat-field-view' }),
    parameters: makeBuffer('sim-parameters', PARAM_BUFFER_BYTES, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST),
    oats: makeBuffer('sim-oats', MAX_OATS * 16, bufferUsage(false)),
    crowdAtomic: makeBuffer('sim-crowd-atomic', fieldTexels * 4, bufferUsage()),
    exposureAtomic: makeBuffer('sim-exposure-atomic', fieldTexels * 4, bufferUsage()),
    dispatchArgs: makeBuffer('sim-dispatch-args', 12, bufferUsage(true) | GPUBufferUsage.INDIRECT),
    renderArgs: makeBuffer('sim-render-args', 16, bufferUsage(true) | GPUBufferUsage.INDIRECT),
    survivorCount: makeBuffer('sim-survivor-count', 4, bufferUsage(true)),
    allocatorDebug: makeBuffer('sim-allocator-debug', 16, bufferUsage(true)),
    childOwnership: makeBuffer('sim-child-ownership', capacity * 4, bufferUsage()),
    stateHash: makeBuffer('sim-state-hash', 32, bufferUsage(true)),
    countReadback: makeBuffer('sim-count-readback', 4, GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ),
    hashReadback: makeBuffer('sim-hash-readback', 32, GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ),
    allocatorReadback: makeBuffer('sim-allocator-readback', 16, GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ),
  };
  resources.all = [
    ...agentBuffers, ...countBuffers, ...dynamicFields, ...crowdFields, oatField,
    resources.parameters, resources.oats, resources.crowdAtomic, resources.exposureAtomic,
    resources.dispatchArgs, resources.renderArgs, resources.survivorCount,
    resources.allocatorDebug, resources.childOwnership, resources.stateHash,
    resources.countReadback, resources.hashReadback, resources.allocatorReadback,
  ];
  return resources;
}

export function destroySimulationResources(registry, resources) {
  for (const resource of resources.all) registry.destroy(resource);
}

export function alignedFieldRowBytes(fieldSize) {
  return Math.ceil((fieldSize * 4) / 256) * 256;
}
export function createSimulationBindings(device, layouts, resources) {
  const bind = (label, layoutName, entries) => device.createBindGroup({
    label,
    layout: layouts[layoutName].bindGroupLayout,
    entries: entries.map((resource, binding) => ({ binding, resource })),
  });
  const buffer = (value) => ({ buffer: value });
  const texture = (view) => view;

  const oat = bind('sim-oat-bind-group', 'oat', [
    buffer(resources.parameters), buffer(resources.oats), texture(resources.oatFieldView),
  ]);
  const crowdScatter = resources.agentBuffers.map((agents, parity) => bind(
    `sim-crowd-scatter-bind-${parity}`,
    'scatter',
    [buffer(resources.parameters), buffer(agents), buffer(resources.countBuffers[parity]), buffer(resources.crowdAtomic)],
  ));
  const crowdResolve = bind('sim-crowd-resolve-bind', 'crowdResolve', [
    buffer(resources.parameters), buffer(resources.crowdAtomic), texture(resources.crowdFieldViews[0]),
  ]);
  const crowdFilter = [0, 1].map((source) => bind(`sim-crowd-filter-bind-${source}`, 'textureFilter', [
    buffer(resources.parameters), texture(resources.crowdFieldViews[source]), texture(resources.crowdFieldViews[source ^ 1]),
  ]));

  const advance = resources.agentBuffers.map((agentsIn, parity) => [0, 1].map((densityIndex) => bind(
    `sim-advance-bind-${parity}-density-${densityIndex}`,
    'advance',
    [
      buffer(resources.parameters), buffer(agentsIn), buffer(resources.agentBuffers[parity ^ 1]),
      buffer(resources.countBuffers[parity]), buffer(resources.countBuffers[parity ^ 1]),
      texture(resources.dynamicFieldViews[0]), texture(resources.oatFieldView),
      texture(resources.crowdFieldViews[densityIndex]),
    ],
  )));
  const birth = resources.agentBuffers.map((agents, parity) => bind(`sim-birth-bind-${parity}`, 'birth', [
    buffer(resources.parameters), buffer(agents), buffer(resources.countBuffers[parity]),
    buffer(resources.survivorCount), buffer(resources.allocatorDebug), buffer(resources.childOwnership),
  ]));
  const indirect = resources.countBuffers.map((count, parity) => bind(`sim-indirect-bind-${parity}`, 'indirect', [
    buffer(resources.parameters), buffer(count), buffer(resources.survivorCount),
    buffer(resources.dispatchArgs), buffer(resources.renderArgs),
  ]));
  const exposure = resources.agentBuffers.map((agents, parity) => bind(`sim-exposure-bind-${parity}`, 'scatter', [
    buffer(resources.parameters), buffer(agents), buffer(resources.countBuffers[parity]), buffer(resources.exposureAtomic),
  ]));
  const diffuse = bind('sim-diffuse-bind', 'field', [
    buffer(resources.parameters), texture(resources.dynamicFieldViews[0]),
    buffer(resources.exposureAtomic), texture(resources.dynamicFieldViews[1]),
  ]);
  const delta = bind('sim-delta-bind', 'field', [
    buffer(resources.parameters), texture(resources.dynamicFieldViews[1]),
    buffer(resources.exposureAtomic), texture(resources.dynamicFieldViews[0]),
  ]);
  const hash = resources.agentBuffers.map((agents, parity) => bind(`sim-hash-bind-${parity}`, 'hash', [
    buffer(resources.parameters), buffer(agents), buffer(resources.countBuffers[parity]),
    texture(resources.dynamicFieldViews[0]), buffer(resources.stateHash),
  ]));
  return { oat, crowdScatter, crowdResolve, crowdFilter, advance, birth, indirect, exposure, diffuse, delta, hash };
}
import { PARAM_BUFFER_BYTES } from './params-layout.js';

export function createSimulationLayouts(device) {
  const compute = GPUShaderStage.COMPUTE;
  const uniform = { buffer: { type: 'uniform', minBindingSize: PARAM_BUFFER_BYTES } };
  const storage = { buffer: { type: 'storage' } };
  const readonly = { buffer: { type: 'read-only-storage' } };
  const sampledField = { texture: { sampleType: 'unfilterable-float', viewDimension: '2d' } };
  const storageField = { storageTexture: { access: 'write-only', format: 'r32float', viewDimension: '2d' } };
  const make = (label, resources) => device.createBindGroupLayout({
    label,
    entries: resources.map((resource, binding) => ({ binding, visibility: compute, ...resource })),
  });

  const layouts = {
    oat: make('sim-oat-layout', [uniform, readonly, storageField]),
    scatter: make('sim-agent-scatter-layout', [uniform, readonly, storage, storage]),
    crowdResolve: make('sim-crowd-resolve-layout', [uniform, storage, storageField]),
    textureFilter: make('sim-texture-filter-layout', [uniform, sampledField, storageField]),
    advance: make('sim-advance-layout', [
      uniform, readonly, storage, storage, storage, sampledField, sampledField, sampledField,
    ]),
    birth: make('sim-birth-layout', [uniform, storage, storage, readonly, storage, storage]),
    indirect: make('sim-indirect-layout', [uniform, storage, storage, storage, storage]),
    field: make('sim-field-layout', [uniform, sampledField, storage, storageField]),
    hash: make('sim-hash-layout', [uniform, readonly, storage, sampledField, storage]),
  };
  return Object.fromEntries(Object.entries(layouts).map(([name, bindGroupLayout]) => [name, {
    bindGroupLayout,
    pipelineLayout: device.createPipelineLayout({ label: `${name}-pipeline-layout`, bindGroupLayouts: [bindGroupLayout] }),
  }]));
}

import { BASE_POPULATION_CONTROL_VALUES } from '../shared/params.js';
import { gameClock } from '../shared/clock.js';

const SAMPLE_LIMIT = 240;
const SUPPLY_EPSILON = 1e-6;
const clamp = (value, low, high) => Math.max(low, Math.min(high, value));
const finite = (value, fallback) => Number.isFinite(Number(value)) ? Number(value) : fallback;

export function createPopulationControllerState(params) {
  return {
    enabled: false,
    target: BASE_POPULATION_CONTROL_VALUES.populationTarget,
    lastSampleTime: null,
    lastCount: null,
    growthRate: 0,
    commandedGrowthRate: 0,
    logPopulationError: 0,
    lastOatSupplyRate: params.oatSupplyRate,
    saturatedLow: false,
    saturatedHigh: false,
    secondarySeverity: 0,
    baseBurnRate: params.burnRate,
    baseReproThreshold: params.reproThreshold,
    samples: [],
  };
}

export function resetPopulationController(params, state, { preserveBase = false } = {}) {
  if (!preserveBase) {
    state.baseBurnRate = params.burnRate;
    state.baseReproThreshold = params.reproThreshold;
  }
  state.enabled = Boolean(params.usePopulationControl);
  state.target = populationTarget(params);
  state.lastSampleTime = null;
  state.lastCount = null;
  state.growthRate = 0;
  state.commandedGrowthRate = 0;
  state.logPopulationError = 0;
  state.lastOatSupplyRate = params.oatSupplyRate;
  state.saturatedLow = false;
  state.saturatedHigh = false;
  state.secondarySeverity = 0;
  state.samples = [];
  return clonePopulationControllerState(state);
}

/** Fresh semantic transcription of main.js:19371–19492. */
export function updatePopulationController(params, state, {
  now,
  visibleAgents,
  force = false,
} = {}) {
  if (!params.usePopulationControl) return clonePopulationControllerState(state);

  const sampleTime = Number.isFinite(Number(now))
    ? Number(now)
    : gameClock.now();
  const target = populationTarget(params);
  const periodMs = Math.max(1, finite(
    params.populationControlPeriodMs,
    BASE_POPULATION_CONTROL_VALUES.populationControlPeriodMs,
  ));
  if (state.lastSampleTime !== null && !force && sampleTime - state.lastSampleTime < periodMs) {
    return clonePopulationControllerState(state);
  }

  const agentCount = Math.max(finite(visibleAgents, 1), 1);
  params.useOatRationing = true;
  state.enabled = true;
  state.target = target;
  state.logPopulationError = Math.log(agentCount / target);
  if (state.lastSampleTime === null || state.lastCount === null) {
    state.lastSampleTime = sampleTime;
    state.lastCount = agentCount;
    state.lastOatSupplyRate = params.oatSupplyRate;
    return clonePopulationControllerState(state);
  }

  const dtSeconds = Math.max((sampleTime - state.lastSampleTime) / 1000, 1e-6);
  const rawGrowthRate = (Math.log(agentCount) - Math.log(Math.max(state.lastCount, 1))) / dtSeconds;
  const emaAlpha = clamp(
    finite(params.populationGrowthEmaAlpha, BASE_POPULATION_CONTROL_VALUES.populationGrowthEmaAlpha),
    0,
    1,
  );
  state.growthRate = state.samples.length === 0
    ? rawGrowthRate
    : state.growthRate + emaAlpha * (rawGrowthRate - state.growthRate);

  const deadband = Math.max(0, finite(
    params.populationDeadbandFraction,
    BASE_POPULATION_CONTROL_VALUES.populationDeadbandFraction,
  ));
  const effectiveLogError = Math.abs(agentCount - target) / target < deadband
    ? 0
    : state.logPopulationError;
  const lambda = Math.max(0, finite(params.populationLambda, BASE_POPULATION_CONTROL_VALUES.populationLambda));
  const commandLimit = Math.max(0, finite(
    params.populationMaxCommandedGrowthRate,
    BASE_POPULATION_CONTROL_VALUES.populationMaxCommandedGrowthRate,
  ));
  state.commandedGrowthRate = clamp(-lambda * effectiveLogError, -commandLimit, commandLimit);

  const growthError = state.commandedGrowthRate - state.growthRate;
  const supplyGain = Math.max(0, finite(
    params.populationSupplyLogGain,
    BASE_POPULATION_CONTROL_VALUES.populationSupplyLogGain,
  ));
  const { min: supplyMin, max: supplyMax } = oatSupplyBounds(params);
  const currentSupply = Math.max(finite(params.oatSupplyRate, supplyMin), SUPPLY_EPSILON);
  const requestedSupply = Math.exp(Math.log(currentSupply) + supplyGain * growthError);
  const nextSupply = clamp(requestedSupply, supplyMin, supplyMax);
  state.saturatedLow = nextSupply <= supplyMin + SUPPLY_EPSILON;
  state.saturatedHigh = nextSupply >= supplyMax - SUPPLY_EPSILON;
  params.oatSupplyRate = nextSupply;
  applySecondaryActuator(params, state, agentCount, target, state.saturatedLow);

  state.lastSampleTime = sampleTime;
  state.lastCount = agentCount;
  state.lastOatSupplyRate = params.oatSupplyRate;
  recordSample(state, sampleTime, agentCount);
  return clonePopulationControllerState(state);
}

export function clonePopulationControllerState(state) {
  return { ...state, samples: state.samples.map((sample) => ({ ...sample })) };
}

export function restorePopulationControllerState(snapshot) {
  return clonePopulationControllerState({ ...snapshot, samples: snapshot.samples ?? [] });
}

function applySecondaryActuator(params, state, agentCount, target, saturatedLow) {
  const growthThreshold = Math.max(0, finite(
    params.populationSecondaryGrowthThreshold,
    BASE_POPULATION_CONTROL_VALUES.populationSecondaryGrowthThreshold,
  ));
  const activationRatio = Math.max(1, finite(
    params.populationSecondaryOvershootRatio,
    BASE_POPULATION_CONTROL_VALUES.populationSecondaryOvershootRatio,
  ));
  let rawSeverity = 0;
  if (params.populationUseSecondaryActuator
      && saturatedLow
      && agentCount > target * activationRatio
      && state.growthRate > growthThreshold) {
    const overshootWindow = Math.max(0.05, activationRatio * 0.35);
    const growthWindow = Math.max(0.01, growthThreshold * 4);
    const overshootSeverity = smoothstep(activationRatio, activationRatio + overshootWindow, agentCount / Math.max(1, target));
    const growthSeverity = smoothstep(growthThreshold, growthThreshold + growthWindow, state.growthRate);
    rawSeverity = clamp(overshootSeverity * growthSeverity, 0, 1);
  }

  const blend = rawSeverity > state.secondarySeverity ? 0.16 : 0.10;
  let severity = state.secondarySeverity + (rawSeverity - state.secondarySeverity) * blend;
  if (severity < 1e-4) severity = 0;
  state.secondarySeverity = clamp(severity, 0, 1);
  const burnBoost = Math.max(0, finite(params.populationBurnBoostMax, BASE_POPULATION_CONTROL_VALUES.populationBurnBoostMax));
  const reproBoost = Math.max(0, finite(params.populationReproBoostMax, BASE_POPULATION_CONTROL_VALUES.populationReproBoostMax));
  params.burnRate = state.baseBurnRate + state.secondarySeverity * burnBoost;
  params.reproThreshold = state.baseReproThreshold + state.secondarySeverity * reproBoost;
}

function populationTarget(params) {
  return Math.max(1, finite(params.populationTarget, BASE_POPULATION_CONTROL_VALUES.populationTarget));
}

function oatSupplyBounds(params) {
  const minimum = Math.max(SUPPLY_EPSILON, finite(
    params.populationOatSupplyMin,
    BASE_POPULATION_CONTROL_VALUES.populationOatSupplyMin,
  ));
  return {
    min: minimum,
    max: Math.max(minimum, finite(params.populationOatSupplyMax, BASE_POPULATION_CONTROL_VALUES.populationOatSupplyMax)),
  };
}

function recordSample(state, time, agents) {
  state.samples.push({
    time,
    agents,
    growthRate: state.growthRate,
    commandedGrowthRate: state.commandedGrowthRate,
    oatSupplyRate: state.lastOatSupplyRate,
    logPopulationError: state.logPopulationError,
    saturatedLow: state.saturatedLow,
    saturatedHigh: state.saturatedHigh,
    secondarySeverity: state.secondarySeverity,
  });
  if (state.samples.length > SAMPLE_LIMIT) state.samples.splice(0, state.samples.length - SAMPLE_LIMIT);
}

function smoothstep(low, high, value) {
  const amount = clamp((value - low) / (high - low), 0, 1);
  return amount * amount * (3 - 2 * amount);
}
